(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-174":{scenario:{company:"Whitecrane Bank",supervisor:{name:"Ngô Thanh Hà",role:{vi:"Trưởng phòng Tuân thủ & Phòng chống rửa tiền",en:"Head of Compliance & AML"}},ref_code:"KYC-6092",title:{vi:"Biết khách hàng thật. Biết chủ sở hữu thật.",en:"Know the real customer. Know the real owner."},brief:{vi:"Bạn rà soát hồ sơ KYC-6092 mở tài khoản cho Công ty X. Cổ đông của X: Công ty H nắm 45%, các cổ đông còn lại mỗi người dưới 10%. Ông K, nguyên thứ trưởng của một nước ngoài, nắm 60% Công ty H. Ngưỡng chủ sở hữu hưởng lợi là 25% (trực tiếp hoặc gián tiếp). Bản nháp chỉ xét sở hữu trực tiếp, kết luận không có chủ sở hữu hưởng lợi và áp dụng CDD thông thường. Hãy sửa hai trường và lập báo cáo có căn cứ.",en:"You are reviewing file KYC-6092 to open an account for Company X. X's shareholders: Company H holds 45%, every other shareholder under 10%. Mr. K, a former deputy minister of a foreign country, owns 60% of Company H. The beneficial ownership threshold is 25% (direct or indirect). The draft looks only at direct ownership, finds no beneficial owner and applies standard CDD. Correct both fields and write an evidence-based report."},reference_title:{vi:"Chính sách KYC & sơ đồ sở hữu đã xác minh · KYC-6092",en:"Approved KYC policy & verified ownership chart · KYC-6092"},fields:[{id:"CDD_LEVEL",label:{vi:"Mức độ nhận biết khách hàng",en:"Due diligence level"},initial:"CDD",expected:"EDD",choices:["SDD","CDD","EDD"],reference:"Chính sách đánh giá rủi ro khách hàng",ref_value:{vi:"Rủi ro thấp: SDD; thông thường: CDD; PEP nước ngoài là khách hàng hoặc chủ sở hữu hưởng lợi: EDD",en:"Low risk: SDD; standard: CDD; foreign PEP as customer or beneficial owner: EDD"},hint:{vi:"Xác định chủ sở hữu hưởng lợi trước, rồi kiểm tra người đó có phải người có ảnh hưởng chính trị nước ngoài không.",en:"Identify the beneficial owner first, then check whether that person is a foreign politically exposed person."}},{id:"UBO_PCT",label:{vi:"Tỷ lệ sở hữu gián tiếp của ông K (%)",en:"Mr. K indirect ownership (%)"},initial:"0",expected:"27",reference:"Sơ đồ cơ cấu sở hữu đã xác minh",ref_value:{vi:"Công ty H nắm 45% Công ty X; ông K nắm 60% Công ty H; ngưỡng 25%",en:"Company H holds 45% of Company X; Mr. K holds 60% of Company H; threshold 25%"},hint:{vi:"Sở hữu gián tiếp qua nhiều tầng được tính bằng tích các tỷ lệ dọc theo chuỗi sở hữu.",en:"Indirect ownership through layers is the product of the percentages along the chain."}}],sop32:{vi:"Tỷ lệ sở hữu gián tiếp = tích các tỷ lệ sở hữu qua từng tầng pháp nhân; cá nhân nắm từ 25% trở lên (trực tiếp và gián tiếp cộng lại) là chủ sở hữu hưởng lợi phải nhận biết, xác minh.",en:"Indirect ownership = product of ownership percentages through each legal layer; an individual holding 25% or more (direct plus indirect) is a beneficial owner to identify and verify."},context:{label:"KYC PORTAL / KYC-6092",metrics:[{label:{vi:"Công ty H tại Công ty X",en:"Company H in Company X"},value:"45%"},{label:{vi:"Ông K tại Công ty H",en:"Mr. K in Company H"},value:"60%"},{label:{vi:"Ngưỡng chủ sở hữu hưởng lợi",en:"Beneficial owner threshold"},value:"25%"}]},crisis:{vi:"Giám đốc chi nhánh nhắn: “Khách sẽ chuyển về 50 tỷ đồng tiền gửi trong tuần. Gỡ cờ PEP đi, mở tài khoản theo CDD thông thường ngay hôm nay, hồ sơ nguồn tiền bổ sung sau cũng được.”",en:"The branch director messages you: “The client will bring 50 billion VND of deposits this week. Remove the PEP flag and open the account under standard CDD today, the source of funds can come later.”"},options:{safe:{vi:"Giữ cờ PEP, áp dụng EDD: xác minh nguồn tiền, nguồn tài sản, xin phê duyệt của quản lý cấp cao trước khi mở tài khoản và báo Trưởng phòng Tuân thủ bằng văn bản.",en:"Keep the PEP flag and apply EDD: verify source of funds and wealth, obtain senior management approval before opening and inform the Head of Compliance in writing."},shortcut:{vi:"Gỡ cờ PEP, mở tài khoản ngay và bổ sung hồ sơ nguồn tiền sau.",en:"Remove the PEP flag, open the account now and collect source of funds later."},wait:{vi:"Không xử lý hồ sơ, chờ chi nhánh tự quyết định.",en:"Leave the file untouched and let the branch decide."}},questions:{vi:["Vì sao ông K là chủ sở hữu hưởng lợi với tỷ lệ 27% và hồ sơ phải áp dụng EDD thay vì CDD?","Nếu giao dịch sau khi mở tài khoản có dấu hiệu bất thường, bạn báo cáo thế nào và tránh hành vi tiết lộ thông tin ra sao?"],en:["Why is Mr. K a beneficial owner at 27% and why does the file require EDD instead of CDD?","If transactions after opening look unusual, how do you report them and how do you avoid tipping off the client?"]},hints:{vi:["Vẽ chuỗi sở hữu từ ông K qua Công ty H tới Công ty X và ghi tỷ lệ từng tầng.","Nhân các tỷ lệ theo SOP mục 3.2 rồi so với ngưỡng 25%.","Đọc SOP mục 4.2: không ai được gỡ cờ PEP hay bỏ qua EDD vì áp lực doanh số."],en:["Draw the chain from Mr. K through Company H to Company X and label each layer's percentage.","Multiply the percentages per SOP 3.2, then compare the result with the 25% threshold.","Re-read SOP 4.2: nobody may remove a PEP flag or skip EDD because of sales pressure."]}},learning:{summary:{vi:"Chuyên viên phòng chống rửa tiền và tuân thủ ngân hàng thiết kế và vận hành chương trình nhận biết khách hàng (KYC, CDD), đánh giá rủi ro, giám sát giao dịch, sàng lọc danh sách cấm vận và PEP, điều tra cảnh báo và lập báo cáo giao dịch đáng ngờ gửi cơ quan có thẩm quyền. Nghề bảo vệ ngân hàng khỏi bị lợi dụng cho tội phạm tài chính, đòi hỏi am hiểu luật, tư duy điều tra và bản lĩnh độc lập.",en:"An AML and KYC compliance officer designs and runs the customer due diligence programme, risk assessments, transaction monitoring and sanctions and PEP screening, investigates alerts and files suspicious transaction reports with the authorities. The role protects the bank from being used for financial crime and requires legal knowledge, an investigative mindset and independence."},responsibilities:{vi:["Rà soát hồ sơ KYC, xác định chủ sở hữu hưởng lợi và xếp hạng rủi ro khách hàng.","Sàng lọc khách hàng, giao dịch với danh sách cấm vận, PEP và danh sách đen.","Điều tra cảnh báo giám sát giao dịch, kết luận và lưu hồ sơ điều tra.","Lập báo cáo giao dịch đáng ngờ, giao dịch giá trị lớn đúng hạn, đúng mẫu.","Đào tạo chi nhánh và cập nhật quy trình theo thay đổi pháp luật."],en:["Review KYC files, identify beneficial owners and rate customer risk.","Screen customers and payments against sanctions, PEP and watch lists.","Investigate monitoring alerts, conclude and document each case.","File suspicious and large-value transaction reports on time and in the right format.","Train branches and update procedures as the law changes."]},competencies:[{name:{vi:"Phân tích cơ cấu sở hữu",en:"Ownership analysis"},desc:{vi:"Lần theo chuỗi pháp nhân nhiều tầng để tìm cá nhân thực sự sở hữu, kiểm soát.",en:"Trace multi-layer corporate chains to find the individuals who truly own or control."}},{name:{vi:"Tiếp cận dựa trên rủi ro",en:"Risk-based approach"},desc:{vi:"Áp dụng SDD, CDD, EDD tương xứng với rủi ro khách hàng, sản phẩm, địa bàn.",en:"Apply SDD, CDD or EDD in line with customer, product and geographic risk."}},{name:{vi:"Điều tra giao dịch",en:"Transaction investigation"},desc:{vi:"Nhận diện chia nhỏ giao dịch, luân chuyển vòng tròn, dòng tiền không phù hợp hồ sơ.",en:"Detect structuring, circular flows and activity inconsistent with the profile."}},{name:{vi:"Viết báo cáo pháp lý",en:"Regulatory reporting"},desc:{vi:"Lập báo cáo giao dịch đáng ngờ rõ dữ kiện, căn cứ và lập luận, đúng thời hạn.",en:"Write suspicious transaction reports with clear facts, grounds and reasoning, on time."}},{name:{vi:"Độc lập & bảo mật",en:"Independence & confidentiality"},desc:{vi:"Giữ kết luận trước áp lực kinh doanh và tuyệt đối không tiết lộ việc báo cáo cho khách.",en:"Hold conclusions against sales pressure and never disclose a report to the client."}}],knowledge:{vi:["Luật Phòng, chống rửa tiền số 14/2022/QH15 và Nghị định 19/2023/NĐ-CP hướng dẫn thi hành.","Thông tư 09/2023/TT-NHNN hướng dẫn thực hiện một số điều của Luật Phòng, chống rửa tiền.","Quyết định 11/2023/QĐ-TTg về mức giá trị giao dịch phải báo cáo (400 triệu đồng).","40 Khuyến nghị của FATF và phương pháp tiếp cận dựa trên rủi ro.","Nhận biết chủ sở hữu hưởng lợi, PEP và các biện pháp nhận biết tăng cường (EDD).","Nghĩa vụ báo cáo giao dịch đáng ngờ, lưu trữ hồ sơ và cấm tiết lộ thông tin."],en:["Anti-Money Laundering Law No. 14/2022/QH15 and implementing Decree 19/2023/ND-CP.","Circular 09/2023/TT-NHNN guiding parts of the Anti-Money Laundering Law.","Decision 11/2023/QD-TTg on the reportable transaction threshold (400 million VND).","The FATF 40 Recommendations and the risk-based approach.","Beneficial ownership, PEPs and enhanced due diligence (EDD) measures.","Suspicious transaction reporting, record keeping and the tipping-off prohibition."]},tools:["KYC / eKYC platform","Transaction monitoring system","Sanctions & PEP screening","Case management tool","Ownership mapping tool","Core Banking"],tools_en:["KYC / eKYC platform","Transaction monitoring system","Sanctions & PEP screening","Case management tool","Ownership mapping tool","Core Banking"],kpis:{vi:["Tỷ lệ cảnh báo được xử lý trong thời hạn quy định.","Tỷ lệ báo cáo giao dịch đáng ngờ nộp đúng hạn, đủ căn cứ.","Tỷ lệ hồ sơ khách hàng rủi ro cao được rà soát định kỳ đúng hạn.","Số phát hiện của thanh tra, kiểm toán về phòng chống rửa tiền (mục tiêu bằng 0)."],en:["Share of alerts closed within the required time.","Share of suspicious transaction reports filed on time with sufficient grounds.","Share of high-risk customers reviewed on schedule.","AML findings from inspections or audits (target zero)."]},day:[{time:"08:00",vi:"Xử lý danh sách cảnh báo sàng lọc cấm vận và PEP phát sinh qua đêm.",en:"Work the overnight sanctions and PEP screening alerts."},{time:"09:30",vi:"Rà soát hồ sơ KYC khách hàng doanh nghiệp mới, xác định chủ sở hữu hưởng lợi.",en:"Review new corporate KYC files and identify beneficial owners."},{time:"11:00",vi:"Điều tra cảnh báo giao dịch tiền mặt chia nhỏ tại một chi nhánh.",en:"Investigate a cash structuring alert at a branch."},{time:"14:00",vi:"Soạn báo cáo giao dịch đáng ngờ và trình Trưởng phòng Tuân thủ ký duyệt.",en:"Draft a suspicious transaction report for the Head of Compliance to sign."},{time:"16:30",vi:"Cập nhật danh sách theo dõi và tài liệu đào tạo cho chi nhánh.",en:"Update watch lists and branch training materials."}],mistakes:{vi:["Chỉ xét cổ đông trực tiếp, bỏ sót chủ sở hữu hưởng lợi gián tiếp qua công ty mẹ.","Gỡ cờ PEP hoặc hạ mức nhận biết vì áp lực huy động vốn.","Tiết lộ cho khách hàng hoặc người không có thẩm quyền về việc đã báo cáo giao dịch đáng ngờ."],en:["Looking only at direct shareholders and missing indirect owners through a parent.","Removing a PEP flag or lowering due diligence because of deposit targets.","Telling the client or unauthorised staff that a suspicious transaction report was filed."]},career:[{vi:"Chuyên viên kiểm tra KYC",en:"KYC analyst"},{vi:"Chuyên viên phòng chống rửa tiền",en:"AML compliance officer"},{vi:"Trưởng phòng Phòng chống rửa tiền",en:"Head of AML"},{vi:"Giám đốc Tuân thủ (CCO)",en:"Chief Compliance Officer (CCO)"}],glossary:[{term:"UBO",vi:"Chủ sở hữu hưởng lợi: cá nhân thực sự sở hữu hoặc chi phối khách hàng là pháp nhân.",en:"Ultimate beneficial owner: the individual who truly owns or controls a corporate customer."},{term:"PEP",vi:"Người có ảnh hưởng chính trị, cần biện pháp nhận biết tăng cường do rủi ro tham nhũng.",en:"Politically exposed person, requiring enhanced measures because of corruption risk."},{term:"EDD",vi:"Nhận biết khách hàng tăng cường: xác minh nguồn tiền, nguồn tài sản và phê duyệt cấp cao.",en:"Enhanced due diligence: verifying source of funds and wealth with senior approval."},{term:"STR",vi:"Báo cáo giao dịch đáng ngờ gửi cơ quan phòng chống rửa tiền khi có dấu hiệu nghi vấn.",en:"Suspicious transaction report filed with the AML authority when red flags appear."},{term:"Tipping-off",vi:"Hành vi tiết lộ cho khách hoặc bên ngoài về việc báo cáo, điều tra; bị pháp luật cấm.",en:"Disclosing a report or investigation to the client or outsiders; prohibited by law."}],quiz:[{q:{vi:"Bà M nắm 40% Công ty A; Công ty A nắm 70% Công ty B. Tỷ lệ sở hữu gián tiếp của bà M tại B là bao nhiêu?",en:"Ms. M owns 40% of Company A; Company A owns 70% of Company B. What is Ms. M's indirect stake in B?"},options:{vi:["40%","70%","28%","110%"],en:["40%","70%","28%","110%"]},answer:2,explain:{vi:"Sở hữu gián tiếp = 40% x 70% = 28%, vượt ngưỡng 25% nên bà M là chủ sở hữu hưởng lợi.",en:"Indirect stake = 40% x 70% = 28%, above 25%, so Ms. M is a beneficial owner."}},{q:{vi:"Mức giá trị giao dịch có giá trị lớn phải báo cáo theo quy định hiện hành của Việt Nam là bao nhiêu?",en:"What is Vietnam's current large-value transaction reporting threshold?"},options:{vi:["100 triệu đồng","400 triệu đồng","300 triệu đồng","1 tỷ đồng"],en:["100 million VND","400 million VND","300 million VND","1 billion VND"]},answer:1,explain:{vi:"Quyết định 11/2023/QĐ-TTg quy định mức giao dịch có giá trị lớn phải báo cáo là 400 triệu đồng.",en:"Decision 11/2023/QD-TTg sets the large-value reporting threshold at 400 million VND."}},{q:{vi:"Sau khi gửi báo cáo giao dịch đáng ngờ, RM hỏi có nên báo cho khách biết không. Trả lời đúng là gì?",en:"After a suspicious transaction report is filed, the RM asks whether to tell the client. What is the right answer?"},options:{vi:["Báo khách để giữ quan hệ","Chỉ báo nếu khách là VIP","Báo sau khi khách rút hết tiền","Không, tiết lộ việc báo cáo là hành vi bị cấm; giữ bí mật và tiếp tục giám sát"],en:["Tell the client to keep the relationship","Tell only VIP clients","Tell after the client withdraws","No, disclosure is prohibited; keep it confidential and keep monitoring"]},answer:3,explain:{vi:"Pháp luật cấm tiết lộ việc báo cáo giao dịch đáng ngờ để không cản trở điều tra.",en:"The law forbids disclosing a suspicious transaction report so investigations are not compromised."}},{q:{vi:"Trường hợp nào bắt buộc áp dụng nhận biết khách hàng tăng cường (EDD)?",en:"Which case always requires enhanced due diligence (EDD)?"},options:{vi:["Khách hàng hoặc chủ sở hữu hưởng lợi là PEP nước ngoài","Mọi khách hàng mở tài khoản mới","Khách gửi tiết kiệm dưới 10 triệu đồng","Nhân viên của chính ngân hàng"],en:["The customer or beneficial owner is a foreign PEP","Every new account holder","Savers depositing under 10 million VND","The bank's own employees"]},answer:0,explain:{vi:"Theo FATF và pháp luật phòng chống rửa tiền, PEP nước ngoài luôn thuộc nhóm phải áp dụng biện pháp tăng cường.",en:"Under FATF and AML law, foreign PEPs always require enhanced measures."}}]}}})})(window.KKR);
